class Solution:
    def mostPlayed(self, plays: List[int], k: int) -> List[int]:
        songs = set(plays)
        counts = {s: sum(1 for p in plays if p == s) for s in songs}
        ranked = sorted(songs, key=lambda s: (-counts[s], s))
        return ranked[:k]

