class Solution {
    public int[] mostPlayed(int[] plays, int k) {
        Set<Integer> songs = new HashSet<>();
        for (int p : plays) songs.add(p);
        Map<Integer, Integer> counts = new HashMap<>();
        for (int s : songs) {
            int c = 0;
            for (int p : plays) if (p == s) c++;
            counts.put(s, c);
        }
        List<Integer> ranked = new ArrayList<>(songs);
        ranked.sort((a, b) -> !counts.get(a).equals(counts.get(b)) ? counts.get(b) - counts.get(a) : Integer.compare(a, b));
        int[] out = new int[k];
        for (int i = 0; i < k; i++) out[i] = ranked.get(i);
        return out;
    }
}

