        vector<pair<int, int>> ranked;
        for (int s : distinct) ranked.push_back({-(int) count(plays.begin(), plays.end(), s), s});
        sort(ranked.begin(), ranked.end());
        vector<int> out;
        for (int i = 0; i < k; i++) out.push_back(ranked[i].second);
        return out;
