typedef struct { int song, plays; } Pair;

static int by_rank(const void* x, const void* y) {
    const Pair *a = x, *b = y;
    if (a->plays != b->plays) return b->plays - a->plays;
    return (a->song > b->song) - (a->song < b->song);
}

int* mostPlayed(int* plays, int playsSize, int k, int* returnSize) {
    Pair* songs = malloc(playsSize * sizeof(Pair));
    int d = 0;
    for (int i = 0; i < playsSize; i++) {
        int seen = 0;
        for (int j = 0; j < d && !seen; j++) seen = songs[j].song == plays[i];
        if (!seen) songs[d++] = (Pair){plays[i], 0};
    }
    for (int j = 0; j < d; j++)
        for (int i = 0; i < playsSize; i++) songs[j].plays += plays[i] == songs[j].song;
    qsort(songs, d, sizeof(Pair), by_rank);
    int* out = malloc(k * sizeof(int));
    for (int i = 0; i < k; i++) out[i] = songs[i].song;
    free(songs);
    *returnSize = k;
    return out;
}

